1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible animated circle with hover effects">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      --bg: #fff;
19	      --fg: #2563eb;
20	      --shadow: rgba(0, 0, 0, 0.1);
21	    }
22	    @media (prefers-color-scheme: dark) {
23	      :root {
24	        --bg: #111;
25	        --fg: #60a5fa;
26	        --shadow: rgba(0, 0, 0, 0.3);
27	      }
28	    }
29	    body {
30	      min-height: 100dvh;
31	      display: grid;
32	      place-items: center;
33	      padding: 1rem;
34	      background: var(--bg);
35	      color: var(--fg);
36	      font-family: system-ui, -apple-system, sans-serif;
37	    }
38	    main {
39	      width: 100%;
40	      display: flex;
41	      justify-content: center;
42	    }
43	    svg {
44	      display: block;
45	      width: min(400px, 100%);
46	      height: auto;
47	      filter: drop-shadow(0 8px 16px var(--shadow));
48	    }
49	    circle {
50	      transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
51	      transform-origin: center;
52	      stroke: var(--fg);
53	      stroke-width: 2;
54	      opacity: 0.9;
55	    }
56	    @media (prefers-reduced-motion: no-preference) {
57	      svg:hover circle {
58	        transform: scale(1.05);
59	        opacity: 1;
60	      }
61	    }
62	  </style>
63	</head>
64	<body>
65	  <main>
66	    <svg viewBox="0 0 400 400" role="img" aria-label="Animated interactive circle" xmlns="http://www.w3.org/2000/svg">
67	      <circle cx="200" cy="200" r="190" fill="currentColor"/>
68	    </svg>
69	  </main>
70	</body>
71	</html>
